import {newTraverse,stepTraverse,nearestTarget,observeTarget,TARGETS} from './simulation.js';
export const HOME={x:10,y:12};
export const TOOLS={outcrop:'imager',soil:'apxs',ridge:'panorama'};
export function newExpedition(){return {...newTraverse('opportunity'),version:1,phase:'briefing',integrating:null,damage:0,dust:'clear',decision:null,photos:0,report:null};}
export function restoreExpedition(raw){try{const s=JSON.parse(raw);if(s?.version!==1||!['briefing','survey','return','report','complete','failed'].includes(s.phase)||!['x','y','heading','battery','distance','elapsed','damage'].every(k=>Number.isFinite(s[k]))||s.x<3||s.x>97||s.y<3||s.y>97||s.battery<0||s.battery>100||s.damage<0||s.damage>100)return newExpedition();const samples=[...new Set((Array.isArray(s.samples)?s.samples:[]).filter(x=>TARGETS.some(t=>t.id===x)))];if(['return','report','complete'].includes(s.phase)&&samples.length!==3)return newExpedition();if(s.phase==='complete'&&(!Number.isFinite(s.report?.score)||s.report.score<0||s.report.score>100))return newExpedition();const phase=s.phase==='survey'&&samples.length===3?'return':s.phase;return {...newExpedition(),phase,x:s.x,y:s.y,heading:s.heading,battery:s.battery,distance:Math.max(0,s.distance),elapsed:Math.max(0,s.elapsed),damage:s.damage,samples,speed:0,integrating:null,dust:s.dust==='incoming'?'incoming':'clear',decision:['continue','conserve'].includes(s.decision)?s.decision:null,photos:Math.max(0,Math.min(4,Number.isFinite(s.photos)?s.photos:0)),complete:phase==='complete',ended:phase==='failed',report:phase==='complete'?{answer:'water',score:s.report.score,observations:3}:null};}catch{return newExpedition();}}
export function startExpedition(s){return s.phase==='briefing'?{...s,phase:'survey'}:s;}
export function beginMeasurement(s,tool,camera){if(s.phase!=='survey')return {state:s,message:'Complete the current mission phase first.'};const t=nearestTarget(s);if(!t||Math.abs(s.speed)>.6)return {state:s,message:'Brake to a stop inside an unvisited station circle.'};if(TOOLS[t.id]!==tool)return {state:s,message:'This station needs '+TOOLS[t.id]+'. Match your instrument to the question.'};if(tool==='panorama'&&camera!=='mast')return {state:s,message:'Switch to the mast camera before recording the ridge panorama.'};if(s.battery<5)return {state:s,message:'Not enough energy to integrate this observation.'};return {state:{...s,integrating:{target:t.id,remaining:3}},message:'Integrating for three training seconds. Remain stationary.'};}
export function advanceExpedition(s,input,dt){if(!['survey','return'].includes(s.phase)||(s.dust==='incoming'&&!s.decision))return s;const old=s;let next=stepTraverse({...s,complete:false},input,dt,s.decision==='conserve'?18:28);next.phase=s.phase;next.damage=s.damage+(next.collision&&!old.collision?12:0);if(s.integrating){if(Math.abs(next.speed)>.6)next.integrating=null;else{const remaining=s.integrating.remaining-dt;if(remaining<=0){const result=observeTarget({...next,complete:false,speed:0});next={...next,...result.state,complete:false,integrating:null};if(s.integrating.target==='ridge')next.photos=s.photos+1;if(next.samples.length===3)next.phase='return';}else next.integrating={...s.integrating,remaining};}}if(next.elapsed>40&&s.dust==='clear')next.dust='incoming';if(next.dust==='incoming'&&next.decision==='continue')next.battery=Math.max(0,next.battery-dt*.13);if(next.damage>=100||next.battery<=0)return {...next,phase:'failed',ended:true,integrating:null};if(next.phase==='return'&&Math.hypot(next.x-HOME.x,next.y-HOME.y)<7&&Math.abs(next.speed)<.6)next.phase='report';return next;}
export function submitReport(s,answer){if(s.phase!=='report')return {state:s,message:'Return to the communications point with all observations first.'};if(answer!=='water')return {state:s,message:'Your data support an ancient-water hypothesis, not a confirmed detection of life. Re-read the evidence and revise your conclusion.'};const score=Math.round(70+Math.max(0,100-s.damage)*.15+s.battery*.15);return {state:{...s,phase:'complete',complete:true,report:{answer,score,observations:s.samples.length}},message:'Science report transmitted. Mission complete.'};}
